integer i;
reg [3:0] r, c;
reg [3:0] r_plus, r_minus, c_plus, c_minus;
reg [3:0] sum;
reg [255:0] q_next;

always @(*) begin
    for (i = 0; i < 256; i = i + 1) begin
        r = i[7:4];
        c = i[3:0];
        r_plus = r + 1'b1;
        r_minus = r - 1'b1;
        c_plus = c + 1'b1;
        c_minus = c - 1'b1;

        sum = q[{r_plus, c_minus}] + q[{r_plus, c}] + q[{r_plus, c_plus}] +
              q[{r, c_minus}]                       + q[{r, c_plus}] +
              q[{r_minus, c_minus}] + q[{r_minus, c}] + q[{r_minus, c_plus}];

        if (sum == 4'd2)
            q_next[i] = q[i];
        else if (sum == 4'd3)
            q_next[i] = 1'b1;
        else
            q_next[i] = 1'b0;
    end
end

always @(posedge clk) begin
    if (load)
        q <= data;
    else
        q <= q_next;
end

endmodule

