localparam WALK_L   = 3'd0,
               WALK_R   = 3'd1,
               FALL_L   = 3'd2,
               FALL_R   = 3'd3,
               DIG_L    = 3'd4,
               DIG_R    = 3'd5,
               SPLATTER = 3'd6;

    reg [2:0] state, next_state;
    reg [7:0] fall_count;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_L;
            fall_count <= 8'd0;
        end else begin
            state <= next_state;
            if (state == FALL_L || state == FALL_R) begin
                if (fall_count < 8'd255)
                    fall_count <= fall_count + 8'd1;
            end else begin
                fall_count <= 8'd0;
            end
        end
    end

    always @(*) begin
        case (state)
            WALK_L: begin
                if (!ground) next_state = FALL_L;
                else if (dig) next_state = DIG_L;
                else if (bump_left) next_state = WALK_R;
                else next_state = WALK_L;
            end
            WALK_R: begin
                if (!ground) next_state = FALL_R;
                else if (dig) next_state = DIG_R;
                else if (bump_right) next_state = WALK_L;
                else next_state = WALK_R;
            end
            FALL_L: begin
                if (ground) begin
                    if (fall_count > 8'd19) next_state = SPLATTER;
                    else next_state = WALK_L;
                end else begin
                    next_state = FALL_L;
                end
            end
            FALL_R: begin
                if (ground) begin
                    if (fall_count > 8'd19) next_state = SPLATTER;
                    else next_state = WALK_R;
                end else begin
                    next_state = FALL_R;
                end
            end
            DIG_L: begin
                if (!ground) next_state = FALL_L;
                else next_state = DIG_L;
            end
            DIG_R: begin
                if (!ground) next_state = FALL_R;
                else next_state = DIG_R;
            end
            SPLATTER: begin
                next_state = SPLATTER;
            end
            default: next_state = WALK_L;
        endcase
    end

    assign walk_left  = (state == WALK_L);
    assign walk_right = (state == WALK_R);
    assign aaah       = (state == FALL_L || state == FALL_R);
    assign digging    = (state == DIG_L || state == DIG_R);

endmodule
